const createButton = document.getElementById("create-disease-button") as HTMLButtonElement;
const popup = document.getElementById("create-disease-popup") as HTMLDivElement;
const cancelButton = document.getElementById("disease-cancel") as HTMLButtonElement;
const submitButton = document.getElementById("disease-submit") as HTMLButtonElement;
const humanSelect = document.getElementById("target-human-select") as HTMLSelectElement;

function populateHumanDropdown() {
  // Copilot autogenerated this function
  const entitySelect = document.getElementById("entity-select") as HTMLSelectElement;
  humanSelect.innerHTML = '<option value="">Select human...</option>';

  for (const option of entitySelect.options) {
    if (option.textContent?.toLowerCase().includes("human")) {
      const clone = option.cloneNode(true) as HTMLOptionElement;
      humanSelect.appendChild(clone);
    }
  }
}

createButton.onclick = () => {
  populateHumanDropdown();
  popup.hidden = false;
};

cancelButton.onclick = () => {
  popup.hidden = true;
};

submitButton.onclick = () => {
  const name = (document.getElementById("disease-name") as HTMLInputElement).value;
  // copilot generated the rest of this function
  const duration = parseFloat((document.getElementById("disease-duration") as HTMLInputElement).value);
  const recovery = parseFloat((document.getElementById("disease-recovery") as HTMLInputElement).value);
  const severity = parseFloat((document.getElementById("disease-severity") as HTMLInputElement).value);
  const target = humanSelect.options[humanSelect.selectedIndex]?.text;

  if (!name || !target) {
    alert("Please enter all required fields.");
    return;
  }

  console.log(`Launching disease '${name}' at ${target}`, { duration, recovery, severity });

  window.dispatchEvent(new CustomEvent("create-disease", {
    detail: {
      name,
      duration,
      recovery,
      severity,
      targetHumanName: target
    }
  }));

  popup.hidden = true;
};
